func TestEvalCaseContextCancelBroadcast1(t *testing.T) {
ctx,cancel:=context.WithCancel(context.Background());defer cancel()
    done:=make(chan error,3);for i:=0;i<3;i++ {go func(){done<-WaitForCancel(ctx)}()};cancel()
    for i:=0;i<3;i++{select{case e:=<-done:if e!=context.Canceled{t.Fatal(e)};case <-time.After(time.Second):t.Fatal("waiter stuck")}}
}
